/**
 * pyvalues.mjs — Python runtime value model.
 *
 * Representation mapping (this mapping is a hard contract for every module):
 *
 *   Python          JavaScript
 *   ------------    ---------------------------------------------
 *   int             BigInt                (arbitrary precision)
 *   float           Number                (IEEE-754 double)
 *   bool            PyBool  (PY_TRUE / PY_FALSE singletons)
 *   None            PyNone  (PY_NONE singleton)
 *   str             string                (JS UTF-16 string)
 *   bytes           PyBytes  (wraps Uint8Array)
 *   list            PyList   (wraps Array)
 *   tuple           PyTuple  (wraps Array)
 *   set             PySet
 *   frozenset       PyFrozenSet
 *   dict            PyDict   (insertion ordered, Python hash/eq semantics)
 *   complex         PyComplex
 *   range           PyRange
 *   function        PyFunction / PyBuiltin
 *   object()        PyObject
