export function rangeLength(r) {
  const { start, stop, step } = r;
  if (step > 0n) return stop > start ? (stop - start + step - 1n) / step : 0n;
  return stop < start ? (start - stop + (-step) - 1n) / (-step) : 0n;
}

export function rangeItems(r) {
  const out = [];
  const n = rangeLength(r);
  for (let i = 0n; i < n; i++) out.push(r.start + i * r.step);
  return out;
}

/** UTF-8 encode a JS string (surrogate pairs handled, lone surrogates -> WTF-8). */
export function utf8Encode(s) {
  const out = [];
  for (const cp of codePoints(s)) {
    if (cp < 0x80) out.push(cp);
    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    else
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
  }
  return new Uint8Array(out);
}

