  "    let s = 't" + NUL + "(';\n" +
  "    for (const it of v.items) s += hashKey(it) + '" + SOH + "';\n" +
  "    return s + ')';";
const newTuple =
  "    // Length-prefix each element so ('a','b') cannot collide with ('ab',).\n" +
  "    let s = 't" + NUL + "(';\n" +
  "    for (const it of v.items) {\n" +
  "      const h = hashKey(it);\n" +
