  "    }\n" +
  "    return s + ')';";

const oldFs = "    return 'F" + NUL + "(' + parts.join('" + SOH + "') + ')';";
const newFs =
  "    return 'F" + NUL + "(' + parts.map((x) => x.length + ':' + x).join('" + SOH + "') + ')';";

